MAKE CODE: Stepper A4988 800 steps
language arduino
// Stepper motor on A4988 driver: moves 800 steps forward and back repeatedly.
// Wiring: STEP -> pin 3, DIR -> pin 2.
// The driver's current limit (Vref) must be set for the specific motor.
// Steps per turn depends on the motor (e.g., 200 for 1.8°) and microstepping.
// This sketch uses 200 steps per turn (full step) for simplicity.
// If using microstepping, multiply 200 by the microstep factor (e.g., 8 for 1/8 step).

#include <AccelStepper.h>

const int stepPin = 3;
const int dirPin = 2;
const int enablePin = 4; // Optional: connect to pin 4 to enable/disable driver

// Define steps per turn. Adjust if using microstepping or a different motor.
// 200 steps = 1.8 degree motor, full step.
const long stepsPerTurn = 200L; 
// Total steps to move back and forth
const long moveSteps = 800L;

// Create AccelStepper instance in DRIVER mode
AccelStepper stepper(AccelStepper::DRIVER, stepPin, dirPin);

void setup() {
  // Initialize enable pin if used (LOW enables the driver)
  if (enablePin > 0) {
    pinMode(enablePin, OUTPUT);
    digitalWrite(enablePin, LOW);
  }

  // Set maximum speed (steps per second)
  stepper.setMaxSpeed(1000);

  // Set acceleration (steps per second squared) for smooth motion
  stepper.setAcceleration(500);

  // Move to the target position (800 steps forward)
  stepper.moveTo(moveSteps);
}

void loop() {
  // Run the stepper
  stepper.run();

  // Check if the current move is complete
  if (stepper.distanceToGo() == 0) {
    // Reverse direction: move back to the start (0 steps)
    // Note: moveTo() sets an absolute position. 
    // If we are at 800, moving to 0 is 800 steps back.
    stepper.moveTo(0);
  }
}
END

code-st-tank-fill.reply:
MAKE CODE: Tank Fill Control
language st
// Tank Fill Control in Structured Text
// Inputs:
//   LowFloat  - Switch on when tank is low (normally open, closes to ground or 24V)
//   HighFloat - Switch on when tank is high
//   FillValve - Output to open the fill valve
// Logic:
//   Open FillValve when LowFloat is active AND HighFloat is NOT active.
//   Close FillValve when HighFloat is active.
//   (Assumes LowFloat is the "start" condition and HighFloat is the "stop" condition)

VAR
    LowFloat : BOOL;
    HighFloat : BOOL;
    FillValve : BOOL;
END_VAR

// Simple logic: Valve is ON if Low is present and High is not present.
// This assumes the LowFloat switch is momentary or latched by the user, 
// but typically for a tank, we want to fill until High is reached.
// If LowFloat is a level sensor that is TRUE when level is LOW, 
// and HighFloat is TRUE when level is HIGH:
// We want to fill if (Level is Low) AND (Level is NOT High).
// However, the prompt says "open... when low float switch comes on".
// This implies a level switch that triggers at the low point.
// Let's assume:
// LowFloat = TRUE when level is below low setpoint.
// HighFloat = TRUE when level is above high setpoint.
// FillValve = TRUE to open.

FillValve := LowFloat AND NOT HighFloat;

END
